import os
import hashlib
import hmac
import unicodedata
from pathlib import PurePosixPath
from flask import Flask, request, jsonify, abort
import secrets

app = Flask(__name__)

SECRET_KEY = os.environ.get('APP_SECRET_KEY', secrets.token_hex(32))
BASE_DIR = '/var/app/documents'
ALLOWED_EXTENSIONS = {'.txt', '.pdf', '.doc', '.docx', '.png', '.jpg'}
MAX_PATH_LENGTH = 255


def generate_access_token(username: str, filepath: str) -> str:
    """Generate HMAC token for authorized file access."""
    msg = f"{username}:{filepath}".encode('utf-8')
    return hmac.new(SECRET_KEY.encode(), msg, hashlib.sha256).hexdigest()


def verify_access_token(username: str, filepath: str, token: str) -> bool:
    """Verify HMAC token using constant-time comparison."""
    expected = generate_access_token(username, filepath)
    return hmac.compare_digest(expected, token)


def is_within_base_dir(real_path: str) -> bool:
    """Safely check that real_path is inside BASE_DIR, avoiding
    prefix-match bypasses like '/var/app/documents_evil'."""
    base = os.path.realpath(BASE_DIR)
    target = os.path.realpath(real_path)
    try:
        return os.path.commonpath([base, target]) == base
    except ValueError:
        return False


def sanitize_filename(filename: str) -> str:
    """Remove null bytes and control characters."""
    filename = filename.replace('\x00', '')
    filename = ''.join(c for c in filename if ord(c) >= 32)
    return filename


def is_path_safe(filepath: str) -> bool:
    """Check if the path is safe - no traversal sequences."""
    # Reject obvious traversal patterns
    if '..' in filepath:
        return False
    if filepath.startswith('/'):
        return False
    if '~' in filepath:
        return False
    # Check each component
    parts = PurePosixPath(filepath).parts
    for part in parts:
        if part.startswith('.'):
            return False
    return True


def check_extension(filepath: str) -> bool:
    """Verify file has an allowed extension."""
    ext = os.path.splitext(filepath)[1].lower()
    return ext in ALLOWED_EXTENSIONS


def resolve_document_path(user_path: str) -> str:
    """Resolve user-provided path to actual filesystem path.

    Security: normalizes path BEFORE validation to prevent
    Unicode-based traversal bypasses.
    """
    # Step 1: Basic sanitization
    cleaned = sanitize_filename(user_path)

    # Step 2: Unicode NFC normalization FIRST for security
    # Must normalize before security checks to prevent bypass
    normalized = unicodedata.normalize('NFC', cleaned)

    # Step 3: Length check on normalized form
    if len(normalized) > MAX_PATH_LENGTH:
        raise ValueError("Path too long")

    # Step 4: Security validation on the normalized path
    if not is_path_safe(normalized):
        raise ValueError("Path traversal detected")

    # Step 5: Extension check on normalized path
    if not check_extension(normalized):
        raise ValueError("File type not allowed")

    # Step 6: Construct final path using the already-normalized string
    full_path = os.path.join(BASE_DIR, normalized)

    return full_path


@app.route('/api/documents/<username>', methods=['GET'])
def get_document(username: str):
    """Retrieve a document with token-based authorization."""
    filepath = request.args.get('path', '')
    token = request.args.get('token', '')

    if not filepath or not token:
        abort(400, description="Missing path or token")

    # Verify authorization
    if not verify_access_token(username, filepath, token):
        abort(403, description="Invalid access token")

    try:
        resolved_path = resolve_document_path(filepath)
    except ValueError as e:
        abort(400, description=str(e))

    # Final safety check - ensure we're still within BASE_DIR
    # Uses os.path.realpath to resolve any remaining symlinks
    real_path = os.path.realpath(resolved_path)
    if not is_within_base_dir(real_path):
        abort(403, description="Access denied")

    if not os.path.isfile(real_path):
        abort(404, description="File not found")

    try:
        with open(real_path, 'rb') as f:
            content = f.read()
        return content, 200, {'Content-Type': 'application/octet-stream'}
    except IOError:
        abort(500, description="Error reading file")


@app.route('/api/documents/<username>/upload', methods=['POST'])
def upload_document(username: str):
    """Upload a document to user's directory."""
    if 'file' not in request.files:
        abort(400, description="No file provided")

    file = request.files['file']
    filename = file.filename or ''

    # Require a valid access token authorizing this upload path
    token = request.form.get('token', '') or request.args.get('token', '')
    if not token or not verify_access_token(username, filename, token):
        abort(403, description="Invalid access token")

    try:
        resolved_path = resolve_document_path(filename)
    except ValueError as e:
        abort(400, description=str(e))

    # Ensure parent directory exists within user space
    real_path = os.path.realpath(resolved_path)
    if not is_within_base_dir(real_path):
        abort(403, description="Access denied")

    os.makedirs(os.path.dirname(real_path), exist_ok=True)
    file.save(real_path)

    # Generate access token for the uploaded file
    new_token = generate_access_token(username, filename)

    return jsonify({
        'status': 'uploaded',
        'path': filename,
        'token': new_token
    }), 201


@app.route('/api/token/<username>', methods=['POST'])
def request_token(username: str):
    """Request an access token for a specific file path.
    Requires session authentication (handled by middleware)."""
    filepath = request.json.get('filepath', '') if request.json else ''

    if not filepath:
        abort(400, description="Missing filepath")

    # Validate the path is legitimate before issuing token
    try:
        resolved = resolve_document_path(filepath)
        real_path = os.path.realpath(resolved)
        if not is_within_base_dir(real_path):
            abort(403)
    except ValueError:
        abort(400, description="Invalid path")

    token = generate_access_token(username, filepath)
    return jsonify({'token': token, 'path': filepath})


if __name__ == '__main__':
    os.makedirs(BASE_DIR, exist_ok=True)
    app.run(host='127.0.0.1', port=8080)
